def variants(offs):
    pts=offs
    out=[]
    for m in [lambda p:p, lambda p:(p[0],-p[1]), lambda p:(-p[0],p[1]), lambda p:(-p[0],-p[1])]:
        a=sorted(m(p) for p in pts)
        for rot in [lambda p:p, lambda p:(-p[1],p[0]), lambda p:(-p[0],-p[1]), lambda p:(p[1],-p[0])]:
            b=sorted(rot(p) for p in a)
            # normalize
            my=min(p[0] for p in b); mx=min(p[1] for p in b)
            n=tuple(sorted((p[0]-my,p[1]-mx) for p in b))
            if n not in out: out.append(n)
    return out
def test_multi(inp,out,seedval,shapeoffs):
    Hh,Ww=len(inp),len(inp[0])
    pred=set()
    for sh in variants(shapeoffs):
        for i in range(Hh):
            for j in range(Ww):
                cand={(i+dy,j+dx) for dy,dx in sh}
                if all(0<=c[0]<Hh and 0<=c[1]<Ww and inp[c[0]][c[1]]==0 for c in cand):
                    pred|=cand
    changed={(i,j) for i in range(Hh) for j in range(Ww) if inp[i][j]!=out[i][j]}
    return pred==changed, sorted(pred^changed)[:10]
